    auto inside=[](const Gate& gate,const UnitState& unit){return std::abs(number(unit.x)-gate.x)<=gate.halfWidth && std::abs(number(unit.y)-gate.y)<=gate.halfHeight;};auto cell=[](float value){return int(std::clamp(std::floor(double(value)/512),double(INT_MIN),double(INT_MAX)));};using Grid=std::map<std::pair<int,int>,std::vector<std::uint32_t>>;auto buildGrid=[&]{Grid grid;for(auto& [id,unit]:units_)if(traveler(*unit) && std::isfinite(number(unit->x)) && std::isfinite(number(unit->y)))grid[{cell(number(unit->x)),cell(number(unit->y))}].push_back(id);return grid;};auto candidates=[&](const Grid& grid,const Gate& gate){std::vector<std::uint32_t> result;auto left=cell(gate.x-gate.halfWidth),right=cell(gate.x+gate.halfWidth),bottom=cell(gate.y-gate.halfHeight),top=cell(gate.y+gate.halfHeight);auto area=(std::int64_t(right)-left+1)*(std::int64_t(top)-bottom+1);if(area>std::int64_t(grid.size())*2){for(auto& [key,ids]:grid)if(key.first>=left && key.first<=right && key.second>=bottom && key.second<=top)result.insert(result.end(),ids.begin(),ids.end());}else for(std::int64_t x=left;x<=right;++x)for(std::int64_t y=bottom;y<=top;++y)if(auto found=grid.find({int(x),int(y)});found!=grid.end())result.insert(result.end(),found->second.begin(),found->second.end());std::sort(result.begin(),result.end());return result;};auto grid=buildGrid();unsigned attempts=0;constexpr unsigned attemptBudget=2;std::set<std::uint32_t> moved;std::map<std::uint32_t,std::set<std::uint32_t>> retry;
